const ASSETS={"/beta/":["<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#123d46\"><meta name=\"robots\" content=\"noindex,nofollow\"><link rel=\"manifest\" href=\"manifest.webmanifest\"><title>AutoJobHunter | Reviewer beta</title><style>*{box-sizing:border-box}body{margin:0;background:#eff5f4;color:#17333c;font:16px/1.5 system-ui}header{background:#123d46;color:white;padding:22px}header b{font-size:25px}header small{display:block;color:#c1dcdb}main{max-width:1000px;margin:auto;padding:20px 18px 60px}h1{font-size:30px;line-height:1.2}h2{font-size:21px}h3{font-size:18px}nav,.row{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}button,a.btn{background:#087567;color:white;border:0;border-radius:9px;padding:12px 15px;font:600 14px system-ui;cursor:pointer;min-height:44px;text-decoration:none}button:disabled{opacity:.45;cursor:not-allowed}nav button{background:white;color:#17333c;border:1px solid #c5d8d7}nav button[aria-current=page]{background:#123d46;color:white}.card{background:white;border:1px solid #d6e4e4;padding:22px;border-radius:14px;margin:16px 0}.notice{background:#e0efeb;border-left:4px solid #087567;padding:14px;border-radius:8px}.warning{background:#fff5df;border-left:4px solid #b97914;padding:12px;border-radius:8px}.muted,small,footer{color:#536b73}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{display:block;font-size:14px;font-weight:650;margin:12px 0 5px}input,select,textarea{width:100%;min-height:44px;border:1px solid #a8bdc2;border-radius:8px;padding:11px;font:15px system-ui;background:white;color:#17333c}textarea{min-height:100px}.check{display:flex;gap:10px;align-items:start}.check input{width:20px;min-height:20px;height:20px}.job{border-top:1px solid #d6e4e4;padding:18px 0}.score{color:#087567;font-size:21px;font-weight:750}a{color:#086b60}[hidden]{display:none!important}#letter{min-height:300px}#status{background:#17333c;color:white;padding:12px;border-radius:8px;position:sticky;bottom:8px}#status:empty{display:none}:focus-visible{outline:3px solid #d38b14;outline-offset:3px}footer{font-size:12px;margin-top:25px}@media(max-width:700px){.grid{grid-template-columns:1fr}.card{padding:17px}h1{font-size:27px}nav button{padding:11px;font-size:13px}}</style></head><body><header><b>AutoJobHunter</b><small>Reviewer beta 0.2 • Your applications. Your approval.</small></header><main><div class=\"notice\"><strong>Independent demonstration, not a government service.</strong> No automatic applications, background job scanning or live AI. Use fictional details. Form contents stay in this browser; hosting may process ordinary request metadata.</div><nav aria-label=\"Main navigation\"><button data-tab=\"home\">Start</button><button data-tab=\"profile\">My profile</button><button data-tab=\"jobs\">Jobs</button><button data-tab=\"draft\">Application</button><button data-tab=\"practice\">Interview</button><button data-tab=\"tracker\">Tracker</button></nav><section id=\"home\"><div class=\"grid\"><div class=\"card\"><small>NO BANK LOGIN • NO ID UPLOAD • NO FEE</small><h1>One suitable job.<br>One confident next step.</h1><p>Save an opportunity, review your fit, prepare a truthful application and keep track of what actually happened.</p><button id=\"sample\">Load fictional demo</button><p><strong id=\"savedCount\">0</strong> saved jobs · <strong id=\"draftCount\">0</strong> drafts · <strong id=\"appliedCount\">0</strong> applications reported</p><div class=\"warning\">This beta is not encrypted case management. Do not enter identification, banking, medical or sensitive third-party information. Reported progress is not verified progress.</div></div><div class=\"card\"><h2>Reviewer walkthrough</h2><p>Load the demo, open Jobs and compare the qualification warnings. Prepare an application, edit it, confirm its accuracy and download the text. Try Interview, then update Tracker. Nothing is sent to an employer.</p><p>On Android, open in Chrome and check its menu for Install app or Add to Home screen. This is a mobile web beta, <strong>not an APK or Play Store release</strong>. Installation and offline behaviour require device testing.</p><a href=\"reviewer-guide.txt\">Reviewer guide and limitations</a></div></div></section><section id=\"profile\" hidden><form id=\"profileForm\" class=\"card\"><h2>Your profile</h2><p>Only include facts you can support.</p><label for=\"name\">Display / sign-off name</label><input id=\"name\" maxlength=\"100\"><label for=\"email\">Reply email (optional)</label><input id=\"email\" type=\"email\" maxlength=\"160\"><label for=\"skills\">Skills, separated by commas</label><input id=\"skills\" maxlength=\"600\"><label for=\"experience\">Relevant experience in your own words</label><textarea id=\"experience\" maxlength=\"3000\"></textarea><label for=\"tickets\">Actual qualifications / licences, separated by commas</label><input id=\"tickets\" maxlength=\"600\"><label for=\"pay\">Preferred minimum hourly pay, CAD</label><input id=\"pay\" type=\"number\" min=\"0\" max=\"500\" step=\".25\"><label for=\"hours\">Preferred schedule</label><select id=\"hours\"><option>Part-time</option><option>Full-time</option><option>Either</option></select><label for=\"area\">Preferred city / area</label><input id=\"area\" maxlength=\"120\"><p><button type=\"submit\">Save profile on this device</button></p></form></section><section id=\"jobs\" hidden><div class=\"grid\"><div class=\"card\"><h2>Saved opportunities</h2><p class=\"muted\">Checklist weights: skills 40%, pay 20%, schedule 20%, location 20%; missing criteria excluded. Not a hiring probability. Qualifications are checked separately and are not validated.</p><div class=\"row\"><a class=\"btn\" href=\"https://vancouver.craigslist.org/search/jjj\" target=\"_blank\" rel=\"noopener noreferrer\">Craigslist jobs</a><a class=\"btn\" href=\"https://www.jobbank.gc.ca/jobsearch/jobsearch\" target=\"_blank\" rel=\"noopener noreferrer\">Job Bank</a></div><div id=\"jobList\"></div></div><form id=\"jobForm\" class=\"card\"><h2>Add a vacancy manually</h2><label for=\"jobTitle\">Job title</label><input id=\"jobTitle\" maxlength=\"160\" required><label for=\"employer\">Employer</label><input id=\"employer\" maxlength=\"160\" required><label for=\"jobUrl\">Original HTTPS URL, optional</label><input id=\"jobUrl\" type=\"url\" maxlength=\"1500\"><label for=\"jobText\">Posting / duties</label><textarea id=\"jobText\" maxlength=\"10000\"></textarea><label for=\"jobPay\">Hourly pay, CAD, optional</label><input id=\"jobPay\" type=\"number\" min=\"0\" max=\"500\" step=\".25\"><label for=\"jobHours\">Schedule</label><select id=\"jobHours\"><option>Unknown</option><option>Part-time</option><option>Full-time</option><option>Either</option></select><label for=\"jobArea\">City / area</label><input id=\"jobArea\" maxlength=\"120\"><label for=\"jobTickets\">Essential qualifications, separated by commas</label><input id=\"jobTickets\" maxlength=\"1000\"><label for=\"closing\">Closing date, optional</label><input id=\"closing\" type=\"date\"><p><button type=\"submit\">Save vacancy</button></p></form></div></section><section id=\"draft\" hidden><div class=\"card\"><h2>Review-first application</h2><label for=\"selectedJob\">Choose a saved job</label><select id=\"selectedJob\"></select><p id=\"requirementNotice\" class=\"warning\"></p><button id=\"generate\">Create local draft</button><p class=\"muted\">A fixed template uses your own experience. This is not AI-generated. Check the original posting, required credentials, file format and submission route.</p><label for=\"letter\">Editable cover letter</label><textarea id=\"letter\" maxlength=\"12000\"></textarea><label class=\"check\"><input id=\"reviewed\" type=\"checkbox\"><span>I reviewed this exact text and removed unsupported claims.</span></label><div class=\"row\"><button id=\"copy\" disabled>Copy reviewed text</button><button id=\"download\" disabled>Download .txt</button></div><p>Downloading is not applying. Submit separately using the employer's permitted channel.</p></div></section><section id=\"practice\" hidden><div class=\"card\"><h2>Interview practice</h2><p id=\"question\" class=\"notice\"></p><button id=\"nextQuestion\">Next practice question</button><label for=\"answer\">Practise a truthful example</label><textarea id=\"answer\" maxlength=\"5000\"></textarea><p><button id=\"practiceCheck\">Show self-review checklist</button></p><p id=\"practiceFeedback\" class=\"notice\" hidden></p><p class=\"muted\">No video, voice, emotion or personality scoring. Answers stay in this open tab and are not included in exported records.</p></div></section><section id=\"tracker\" hidden><div class=\"card\"><h2>Your activity tracker</h2><p>All stages are self-reported. No verification or notification to an employer or government occurs. Follow-up dates are display-only, not background reminders.</p><button id=\"export\">Export local records (.json)</button><div id=\"trackerList\"></div></div><div class=\"card\"><h2>Your data, your choice</h2><p>Browser storage is not encrypted by this app. Device access can expose entries. Browser clearing or uninstalling may remove them. Export only to a private location.</p><button id=\"erase\">Erase all beta data on this device</button><p>Exports saved elsewhere are not erased.</p></div></section><footer>AutoJobHunter reviewer beta 0.2. No WorkBC endorsement, funding approval or research enrolment. No paid APIs or Replit. Physical Android, accessibility, installation, offline and security acceptance tests remain outstanding.</footer><div id=\"status\" role=\"status\" aria-live=\"polite\"></div></main><script>\n'use strict';const $=id=>document.getElementById(id),KEY='autojobhunter-reviewer-v02';const blank=()=>({version:2,profile:{name:'',email:'',skills:'',experience:'',tickets:'',pay:25,hours:'Part-time',area:'Vancouver'},jobs:[],drafts:{},drafted:[]});let state=blank(),qi=0;try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&s.version===2&&s.profile&&Array.isArray(s.jobs)&&s.drafts&&Array.isArray(s.drafted))state=s}catch{}\nconst stages=['Saved','Drafted','Applied — self-reported','Employer reply — self-reported','Interview — self-reported','Offer — self-reported','Hired — self-reported','Closed / not proceeding'];const questions=['Tell me about a time you solved a practical problem at work.','How would you handle a task you have not been trained to do safely?','How do you prioritise several urgent requests?','What interests you about this role?','Describe a disagreement you handled respectfully.'];function say(t){$('status').textContent=t}function counters(){$('savedCount').textContent=state.jobs.length;$('draftCount').textContent=state.drafted.length;$('appliedCount').textContent=state.jobs.filter(j=>stages.slice(2,7).includes(j.stage)).length}function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{say('Storage unavailable. Export before closing this tab.')}counters()}function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}function btn(text,fn){const b=node('button',text);b.type='button';b.onclick=fn;return b}function terms(s){return String(s||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean)}function safeUrl(s){try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}function profileForm(){for(const k of Object.keys(state.profile))if($(k))$(k).value=state.profile[k]}function tab(id){document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(id==='jobs')jobs();if(id==='tracker')tracker();if(id==='draft')select();if(id==='profile')profileForm();window.scrollTo(0,0)}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));\nfunction fit(j){const p=state.profile,c=[],w=terms(p.skills),t=(j.title+' '+j.text).toLowerCase();if(w.length){const n=w.filter(x=>t.includes(x)).length;c.push([40,n/w.length,'Skills mentioned '+n+'/'+w.length])}if(Number(p.pay)>0&&j.pay!==null)c.push([20,j.pay>=p.pay?1:0,'Pay '+(j.pay>=p.pay?'meets':'below')+' preference']);if(j.hours!=='Unknown')c.push([20,p.hours==='Either'||j.hours==='Either'||j.hours===p.hours?1:0,'Schedule '+j.hours]);if(p.area&&j.area)c.push([20,j.area.toLowerCase().includes(p.area.toLowerCase())?1:0,'Area '+j.area]);const total=c.reduce((a,x)=>a+x[0],0);return{score:total?Math.round(100*c.reduce((a,x)=>a+x[0]*x[1],0)/total):null,labels:c.map(x=>x[2]),missing:terms(j.tickets).filter(x=>!terms(p.tickets).includes(x))}}function warning(j){const m=fit(j).missing;return m.length?'Check essential qualifications: '+m.join(', ')+'. Not listed in your profile. Do not claim them unless true.':terms(j.tickets).length?'Entered qualification text matches your profile. Validity and equivalence are NOT verified.':'No essential qualifications entered. Check the complete original posting.'}\n$('profileForm').onsubmit=e=>{e.preventDefault();for(const k of Object.keys(state.profile))state.profile[k]=k==='pay'?Number($(k).value):$(k).value.trim();save();say('Profile saved locally. Existing drafts are not automatically rewritten.')};function jobs(){const list=$('jobList');list.replaceChildren();if(!state.jobs.length)list.append(node('p','No jobs yet. Load the demo or add a vacancy.'));state.jobs.forEach(j=>{const f=fit(j),a=node('article',undefined,'job');a.append(node('h3',j.title),node('p',j.employer+' · '+(j.area||'Area unknown')+' · '+(j.pay===null?'Pay unknown':'$'+j.pay+'/hour')+' · '+j.hours),node('strong',j.demo?'FICTIONAL DEMO VACANCY':'User-entered vacancy; not verified'),node('p',f.score===null?'Unscored':f.score+'% checklist fit','score'),node('p',f.labels.join(' | ')),node('p',warning(j),'warning'));if(j.closing&&j.closing<new Date().toISOString().slice(0,10))a.append(node('p','Closing date has passed. Confirm availability.','warning'));a.append(btn('Prepare application',()=>{tab('draft');$('selectedJob').value=j.id;loadDraft()}));if(j.url&&safeUrl(j.url)){const link=node('a',' Open source vacancy');link.href=j.url;link.target='_blank';link.rel='noopener noreferrer';a.append(link)}list.append(a)})}\n$('jobForm').onsubmit=e=>{e.preventDefault();const url=$('jobUrl').value.trim();if(url&&!safeUrl(url)){say('Use an HTTPS URL without embedded credentials.');return}state.jobs.push({id:typeof crypto.randomUUID==='function'?crypto.randomUUID():String(Date.now()),title:$('jobTitle').value.trim(),employer:$('employer').value.trim(),url,text:$('jobText').value.trim(),pay:$('jobPay').value===''?null:Number($('jobPay').value),hours:$('jobHours').value,area:$('jobArea').value.trim(),tickets:$('jobTickets').value.trim(),closing:$('closing').value,stage:'Saved',note:'',next:'',demo:false});save();e.target.reset();jobs();say('Vacancy saved. Its authenticity and availability are not verified.')};function chosen(){return state.jobs.find(j=>j.id===$('selectedJob').value)}function select(){const old=$('selectedJob').value;$('selectedJob').replaceChildren();state.jobs.forEach(j=>{const o=node('option',j.title+' — '+j.employer);o.value=j.id;$('selectedJob').append(o)});if(state.jobs.some(j=>j.id===old))$('selectedJob').value=old;$('generate').disabled=!state.jobs.length;loadDraft()}function reviewed(){const ready=$('reviewed').checked&&$('letter').value.trim().length>0;$('copy').disabled=!ready;$('download').disabled=!ready}function loadDraft(){const j=chosen();$('letter').value=j?(state.drafts[j.id]||''):'';$('requirementNotice').textContent=j?warning(j):'Save a job first.';$('reviewed').checked=false;reviewed()}$('selectedJob').onchange=loadDraft;\n$('generate').onclick=()=>{const j=chosen();if(!j)return;const p=state.profile,lines=['Dear Hiring Manager,','','I am applying for the '+j.title+' position at '+j.employer+'.','',p.experience?'My relevant experience: '+p.experience:'[Add your truthful relevant experience.]','','I would welcome an opportunity to discuss the role and confirm its requirements.','','Thank you for your consideration.','','Sincerely,',p.name||'[Your name]'];if(p.email)lines.push(p.email);$('letter').value=lines.join('\\n');state.drafts[j.id]=$('letter').value;if(!state.drafted.includes(j.id))state.drafted.push(j.id);if(j.stage==='Saved')j.stage='Drafted';$('reviewed').checked=false;reviewed();save();say('Template draft created; nothing sent.')};$('letter').oninput=()=>{const j=chosen();if(j){state.drafts[j.id]=$('letter').value;save()}$('reviewed').checked=false;reviewed()};$('reviewed').onchange=reviewed;function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=node('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}$('download').onclick=()=>{if(!$('download').disabled)download('autojobhunter-reviewed-application.txt',$('letter').value,'text/plain;charset=utf-8')};$('copy').onclick=async()=>{if($('copy').disabled)return;try{await navigator.clipboard.writeText($('letter').value);say('Reviewed text copied; nothing sent.')}catch{say('Clipboard unavailable. Use Download .txt or select the text manually.')}};\n$('question').textContent=questions[0];$('nextQuestion').onclick=()=>{qi=(qi+1)%questions.length;$('question').textContent=questions[qi];$('practiceFeedback').hidden=true};$('practiceCheck').onclick=()=>{$('practiceFeedback').hidden=false;$('practiceFeedback').textContent='You wrote '+$('answer').value.trim().split(/\\s+/).filter(Boolean).length+' words. Self-check: Is the example real? Did you explain your action and result? How does it relate to this job? This is a checklist, not an AI assessment.'};\nfunction tracker(){const l=$('trackerList');l.replaceChildren();state.jobs.forEach(j=>{const a=node('article',undefined,'job');a.append(node('h3',j.title),node('p',j.employer+(j.demo?' · Fictional':'')));const label=node('label','Progress status');label.htmlFor='s-'+j.id;const s=node('select');s.id=label.htmlFor;stages.forEach(t=>{const o=node('option',t);o.value=t;s.append(o)});s.value=j.stage;s.onchange=()=>{j.stage=s.value;save();say('Self-reported status saved; no verification occurred.')};const nl=node('label','Evidence reference / next action — no sensitive details');nl.htmlFor='n-'+j.id;const n=node('textarea');n.id=nl.htmlFor;n.maxLength=1000;n.value=j.note||'';n.onchange=()=>{j.note=n.value;save()};const dl=node('label','Follow-up date — display only');dl.htmlFor='d-'+j.id;const d=node('input');d.id=dl.htmlFor;d.type='date';d.value=j.next||'';d.onchange=()=>{j.next=d.value;save()};a.append(label,s,nl,n,dl,d);l.append(a)})}$('export').onclick=()=>download('autojobhunter-local-records.json',JSON.stringify({exportedAt:new Date().toISOString(),verification:'All progress is self-reported, not independently verified.',...state},null,2),'application/json');$('erase').onclick=()=>{if(!confirm('Erase all local beta data? Saved exports are not erased.'))return;try{localStorage.removeItem(KEY)}catch{}state=blank();$('letter').value='';$('reviewed').checked=false;$('answer').value='';$('practiceFeedback').hidden=true;reviewed();profileForm();counters();tracker();jobs();say('Local beta data erased.')};\n$('sample').onclick=()=>{if(state.jobs.length&&!confirm('Replace local beta data with fictional records?'))return;state=blank();state.profile={name:'Demo Applicant',email:'demo@example.invalid',skills:'cleaning, maintenance, painting',experience:'I have experience cleaning common areas, painting rooms and helping with routine building maintenance.',tickets:'',pay:25,hours:'Part-time',area:'Vancouver'};state.jobs=[{id:'demo-1',title:'Building Maintenance Assistant',employer:'Example Community Building (fictional)',url:'',text:'Cleaning, painting, maintenance and resident service.',pay:28,hours:'Part-time',area:'Vancouver',tickets:'',closing:'',demo:true,stage:'Saved',note:'',next:''},{id:'demo-2',title:'Facilities Technician',employer:'Example Facilities Team (fictional)',url:'',text:'Maintenance, electrical troubleshooting and shift coverage.',pay:32,hours:'Full-time',area:'Burnaby',tickets:'Red Seal electrician',closing:'',demo:true,stage:'Saved',note:'',next:''}];save();profileForm();tab('jobs');say('Fictional sample loaded; no actual vacancy or employment outcome claimed.')};if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('sw.js',{scope:'./'}).catch(()=>{});profileForm();counters();tab('home');\n</script></body></html>","text/html; charset=utf-8"],"/beta/index.html":["<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#123d46\"><meta name=\"robots\" content=\"noindex,nofollow\"><link rel=\"manifest\" href=\"manifest.webmanifest\"><title>AutoJobHunter | Reviewer beta</title><style>*{box-sizing:border-box}body{margin:0;background:#eff5f4;color:#17333c;font:16px/1.5 system-ui}header{background:#123d46;color:white;padding:22px}header b{font-size:25px}header small{display:block;color:#c1dcdb}main{max-width:1000px;margin:auto;padding:20px 18px 60px}h1{font-size:30px;line-height:1.2}h2{font-size:21px}h3{font-size:18px}nav,.row{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}button,a.btn{background:#087567;color:white;border:0;border-radius:9px;padding:12px 15px;font:600 14px system-ui;cursor:pointer;min-height:44px;text-decoration:none}button:disabled{opacity:.45;cursor:not-allowed}nav button{background:white;color:#17333c;border:1px solid #c5d8d7}nav button[aria-current=page]{background:#123d46;color:white}.card{background:white;border:1px solid #d6e4e4;padding:22px;border-radius:14px;margin:16px 0}.notice{background:#e0efeb;border-left:4px solid #087567;padding:14px;border-radius:8px}.warning{background:#fff5df;border-left:4px solid #b97914;padding:12px;border-radius:8px}.muted,small,footer{color:#536b73}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{display:block;font-size:14px;font-weight:650;margin:12px 0 5px}input,select,textarea{width:100%;min-height:44px;border:1px solid #a8bdc2;border-radius:8px;padding:11px;font:15px system-ui;background:white;color:#17333c}textarea{min-height:100px}.check{display:flex;gap:10px;align-items:start}.check input{width:20px;min-height:20px;height:20px}.job{border-top:1px solid #d6e4e4;padding:18px 0}.score{color:#087567;font-size:21px;font-weight:750}a{color:#086b60}[hidden]{display:none!important}#letter{min-height:300px}#status{background:#17333c;color:white;padding:12px;border-radius:8px;position:sticky;bottom:8px}#status:empty{display:none}:focus-visible{outline:3px solid #d38b14;outline-offset:3px}footer{font-size:12px;margin-top:25px}@media(max-width:700px){.grid{grid-template-columns:1fr}.card{padding:17px}h1{font-size:27px}nav button{padding:11px;font-size:13px}}</style></head><body><header><b>AutoJobHunter</b><small>Reviewer beta 0.2 • Your applications. Your approval.</small></header><main><div class=\"notice\"><strong>Independent demonstration, not a government service.</strong> No automatic applications, background job scanning or live AI. Use fictional details. Form contents stay in this browser; hosting may process ordinary request metadata.</div><nav aria-label=\"Main navigation\"><button data-tab=\"home\">Start</button><button data-tab=\"profile\">My profile</button><button data-tab=\"jobs\">Jobs</button><button data-tab=\"draft\">Application</button><button data-tab=\"practice\">Interview</button><button data-tab=\"tracker\">Tracker</button></nav><section id=\"home\"><div class=\"grid\"><div class=\"card\"><small>NO BANK LOGIN • NO ID UPLOAD • NO FEE</small><h1>One suitable job.<br>One confident next step.</h1><p>Save an opportunity, review your fit, prepare a truthful application and keep track of what actually happened.</p><button id=\"sample\">Load fictional demo</button><p><strong id=\"savedCount\">0</strong> saved jobs · <strong id=\"draftCount\">0</strong> drafts · <strong id=\"appliedCount\">0</strong> applications reported</p><div class=\"warning\">This beta is not encrypted case management. Do not enter identification, banking, medical or sensitive third-party information. Reported progress is not verified progress.</div></div><div class=\"card\"><h2>Reviewer walkthrough</h2><p>Load the demo, open Jobs and compare the qualification warnings. Prepare an application, edit it, confirm its accuracy and download the text. Try Interview, then update Tracker. Nothing is sent to an employer.</p><p>On Android, open in Chrome and check its menu for Install app or Add to Home screen. This is a mobile web beta, <strong>not an APK or Play Store release</strong>. Installation and offline behaviour require device testing.</p><a href=\"reviewer-guide.txt\">Reviewer guide and limitations</a></div></div></section><section id=\"profile\" hidden><form id=\"profileForm\" class=\"card\"><h2>Your profile</h2><p>Only include facts you can support.</p><label for=\"name\">Display / sign-off name</label><input id=\"name\" maxlength=\"100\"><label for=\"email\">Reply email (optional)</label><input id=\"email\" type=\"email\" maxlength=\"160\"><label for=\"skills\">Skills, separated by commas</label><input id=\"skills\" maxlength=\"600\"><label for=\"experience\">Relevant experience in your own words</label><textarea id=\"experience\" maxlength=\"3000\"></textarea><label for=\"tickets\">Actual qualifications / licences, separated by commas</label><input id=\"tickets\" maxlength=\"600\"><label for=\"pay\">Preferred minimum hourly pay, CAD</label><input id=\"pay\" type=\"number\" min=\"0\" max=\"500\" step=\".25\"><label for=\"hours\">Preferred schedule</label><select id=\"hours\"><option>Part-time</option><option>Full-time</option><option>Either</option></select><label for=\"area\">Preferred city / area</label><input id=\"area\" maxlength=\"120\"><p><button type=\"submit\">Save profile on this device</button></p></form></section><section id=\"jobs\" hidden><div class=\"grid\"><div class=\"card\"><h2>Saved opportunities</h2><p class=\"muted\">Checklist weights: skills 40%, pay 20%, schedule 20%, location 20%; missing criteria excluded. Not a hiring probability. Qualifications are checked separately and are not validated.</p><div class=\"row\"><a class=\"btn\" href=\"https://vancouver.craigslist.org/search/jjj\" target=\"_blank\" rel=\"noopener noreferrer\">Craigslist jobs</a><a class=\"btn\" href=\"https://www.jobbank.gc.ca/jobsearch/jobsearch\" target=\"_blank\" rel=\"noopener noreferrer\">Job Bank</a></div><div id=\"jobList\"></div></div><form id=\"jobForm\" class=\"card\"><h2>Add a vacancy manually</h2><label for=\"jobTitle\">Job title</label><input id=\"jobTitle\" maxlength=\"160\" required><label for=\"employer\">Employer</label><input id=\"employer\" maxlength=\"160\" required><label for=\"jobUrl\">Original HTTPS URL, optional</label><input id=\"jobUrl\" type=\"url\" maxlength=\"1500\"><label for=\"jobText\">Posting / duties</label><textarea id=\"jobText\" maxlength=\"10000\"></textarea><label for=\"jobPay\">Hourly pay, CAD, optional</label><input id=\"jobPay\" type=\"number\" min=\"0\" max=\"500\" step=\".25\"><label for=\"jobHours\">Schedule</label><select id=\"jobHours\"><option>Unknown</option><option>Part-time</option><option>Full-time</option><option>Either</option></select><label for=\"jobArea\">City / area</label><input id=\"jobArea\" maxlength=\"120\"><label for=\"jobTickets\">Essential qualifications, separated by commas</label><input id=\"jobTickets\" maxlength=\"1000\"><label for=\"closing\">Closing date, optional</label><input id=\"closing\" type=\"date\"><p><button type=\"submit\">Save vacancy</button></p></form></div></section><section id=\"draft\" hidden><div class=\"card\"><h2>Review-first application</h2><label for=\"selectedJob\">Choose a saved job</label><select id=\"selectedJob\"></select><p id=\"requirementNotice\" class=\"warning\"></p><button id=\"generate\">Create local draft</button><p class=\"muted\">A fixed template uses your own experience. This is not AI-generated. Check the original posting, required credentials, file format and submission route.</p><label for=\"letter\">Editable cover letter</label><textarea id=\"letter\" maxlength=\"12000\"></textarea><label class=\"check\"><input id=\"reviewed\" type=\"checkbox\"><span>I reviewed this exact text and removed unsupported claims.</span></label><div class=\"row\"><button id=\"copy\" disabled>Copy reviewed text</button><button id=\"download\" disabled>Download .txt</button></div><p>Downloading is not applying. Submit separately using the employer's permitted channel.</p></div></section><section id=\"practice\" hidden><div class=\"card\"><h2>Interview practice</h2><p id=\"question\" class=\"notice\"></p><button id=\"nextQuestion\">Next practice question</button><label for=\"answer\">Practise a truthful example</label><textarea id=\"answer\" maxlength=\"5000\"></textarea><p><button id=\"practiceCheck\">Show self-review checklist</button></p><p id=\"practiceFeedback\" class=\"notice\" hidden></p><p class=\"muted\">No video, voice, emotion or personality scoring. Answers stay in this open tab and are not included in exported records.</p></div></section><section id=\"tracker\" hidden><div class=\"card\"><h2>Your activity tracker</h2><p>All stages are self-reported. No verification or notification to an employer or government occurs. Follow-up dates are display-only, not background reminders.</p><button id=\"export\">Export local records (.json)</button><div id=\"trackerList\"></div></div><div class=\"card\"><h2>Your data, your choice</h2><p>Browser storage is not encrypted by this app. Device access can expose entries. Browser clearing or uninstalling may remove them. Export only to a private location.</p><button id=\"erase\">Erase all beta data on this device</button><p>Exports saved elsewhere are not erased.</p></div></section><footer>AutoJobHunter reviewer beta 0.2. No WorkBC endorsement, funding approval or research enrolment. No paid APIs or Replit. Physical Android, accessibility, installation, offline and security acceptance tests remain outstanding.</footer><div id=\"status\" role=\"status\" aria-live=\"polite\"></div></main><script>\n'use strict';const $=id=>document.getElementById(id),KEY='autojobhunter-reviewer-v02';const blank=()=>({version:2,profile:{name:'',email:'',skills:'',experience:'',tickets:'',pay:25,hours:'Part-time',area:'Vancouver'},jobs:[],drafts:{},drafted:[]});let state=blank(),qi=0;try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&s.version===2&&s.profile&&Array.isArray(s.jobs)&&s.drafts&&Array.isArray(s.drafted))state=s}catch{}\nconst stages=['Saved','Drafted','Applied — self-reported','Employer reply — self-reported','Interview — self-reported','Offer — self-reported','Hired — self-reported','Closed / not proceeding'];const questions=['Tell me about a time you solved a practical problem at work.','How would you handle a task you have not been trained to do safely?','How do you prioritise several urgent requests?','What interests you about this role?','Describe a disagreement you handled respectfully.'];function say(t){$('status').textContent=t}function counters(){$('savedCount').textContent=state.jobs.length;$('draftCount').textContent=state.drafted.length;$('appliedCount').textContent=state.jobs.filter(j=>stages.slice(2,7).includes(j.stage)).length}function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{say('Storage unavailable. Export before closing this tab.')}counters()}function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}function btn(text,fn){const b=node('button',text);b.type='button';b.onclick=fn;return b}function terms(s){return String(s||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean)}function safeUrl(s){try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}function profileForm(){for(const k of Object.keys(state.profile))if($(k))$(k).value=state.profile[k]}function tab(id){document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(id==='jobs')jobs();if(id==='tracker')tracker();if(id==='draft')select();if(id==='profile')profileForm();window.scrollTo(0,0)}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));\nfunction fit(j){const p=state.profile,c=[],w=terms(p.skills),t=(j.title+' '+j.text).toLowerCase();if(w.length){const n=w.filter(x=>t.includes(x)).length;c.push([40,n/w.length,'Skills mentioned '+n+'/'+w.length])}if(Number(p.pay)>0&&j.pay!==null)c.push([20,j.pay>=p.pay?1:0,'Pay '+(j.pay>=p.pay?'meets':'below')+' preference']);if(j.hours!=='Unknown')c.push([20,p.hours==='Either'||j.hours==='Either'||j.hours===p.hours?1:0,'Schedule '+j.hours]);if(p.area&&j.area)c.push([20,j.area.toLowerCase().includes(p.area.toLowerCase())?1:0,'Area '+j.area]);const total=c.reduce((a,x)=>a+x[0],0);return{score:total?Math.round(100*c.reduce((a,x)=>a+x[0]*x[1],0)/total):null,labels:c.map(x=>x[2]),missing:terms(j.tickets).filter(x=>!terms(p.tickets).includes(x))}}function warning(j){const m=fit(j).missing;return m.length?'Check essential qualifications: '+m.join(', ')+'. Not listed in your profile. Do not claim them unless true.':terms(j.tickets).length?'Entered qualification text matches your profile. Validity and equivalence are NOT verified.':'No essential qualifications entered. Check the complete original posting.'}\n$('profileForm').onsubmit=e=>{e.preventDefault();for(const k of Object.keys(state.profile))state.profile[k]=k==='pay'?Number($(k).value):$(k).value.trim();save();say('Profile saved locally. Existing drafts are not automatically rewritten.')};function jobs(){const list=$('jobList');list.replaceChildren();if(!state.jobs.length)list.append(node('p','No jobs yet. Load the demo or add a vacancy.'));state.jobs.forEach(j=>{const f=fit(j),a=node('article',undefined,'job');a.append(node('h3',j.title),node('p',j.employer+' · '+(j.area||'Area unknown')+' · '+(j.pay===null?'Pay unknown':'$'+j.pay+'/hour')+' · '+j.hours),node('strong',j.demo?'FICTIONAL DEMO VACANCY':'User-entered vacancy; not verified'),node('p',f.score===null?'Unscored':f.score+'% checklist fit','score'),node('p',f.labels.join(' | ')),node('p',warning(j),'warning'));if(j.closing&&j.closing<new Date().toISOString().slice(0,10))a.append(node('p','Closing date has passed. Confirm availability.','warning'));a.append(btn('Prepare application',()=>{tab('draft');$('selectedJob').value=j.id;loadDraft()}));if(j.url&&safeUrl(j.url)){const link=node('a',' Open source vacancy');link.href=j.url;link.target='_blank';link.rel='noopener noreferrer';a.append(link)}list.append(a)})}\n$('jobForm').onsubmit=e=>{e.preventDefault();const url=$('jobUrl').value.trim();if(url&&!safeUrl(url)){say('Use an HTTPS URL without embedded credentials.');return}state.jobs.push({id:typeof crypto.randomUUID==='function'?crypto.randomUUID():String(Date.now()),title:$('jobTitle').value.trim(),employer:$('employer').value.trim(),url,text:$('jobText').value.trim(),pay:$('jobPay').value===''?null:Number($('jobPay').value),hours:$('jobHours').value,area:$('jobArea').value.trim(),tickets:$('jobTickets').value.trim(),closing:$('closing').value,stage:'Saved',note:'',next:'',demo:false});save();e.target.reset();jobs();say('Vacancy saved. Its authenticity and availability are not verified.')};function chosen(){return state.jobs.find(j=>j.id===$('selectedJob').value)}function select(){const old=$('selectedJob').value;$('selectedJob').replaceChildren();state.jobs.forEach(j=>{const o=node('option',j.title+' — '+j.employer);o.value=j.id;$('selectedJob').append(o)});if(state.jobs.some(j=>j.id===old))$('selectedJob').value=old;$('generate').disabled=!state.jobs.length;loadDraft()}function reviewed(){const ready=$('reviewed').checked&&$('letter').value.trim().length>0;$('copy').disabled=!ready;$('download').disabled=!ready}function loadDraft(){const j=chosen();$('letter').value=j?(state.drafts[j.id]||''):'';$('requirementNotice').textContent=j?warning(j):'Save a job first.';$('reviewed').checked=false;reviewed()}$('selectedJob').onchange=loadDraft;\n$('generate').onclick=()=>{const j=chosen();if(!j)return;const p=state.profile,lines=['Dear Hiring Manager,','','I am applying for the '+j.title+' position at '+j.employer+'.','',p.experience?'My relevant experience: '+p.experience:'[Add your truthful relevant experience.]','','I would welcome an opportunity to discuss the role and confirm its requirements.','','Thank you for your consideration.','','Sincerely,',p.name||'[Your name]'];if(p.email)lines.push(p.email);$('letter').value=lines.join('\\n');state.drafts[j.id]=$('letter').value;if(!state.drafted.includes(j.id))state.drafted.push(j.id);if(j.stage==='Saved')j.stage='Drafted';$('reviewed').checked=false;reviewed();save();say('Template draft created; nothing sent.')};$('letter').oninput=()=>{const j=chosen();if(j){state.drafts[j.id]=$('letter').value;save()}$('reviewed').checked=false;reviewed()};$('reviewed').onchange=reviewed;function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=node('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}$('download').onclick=()=>{if(!$('download').disabled)download('autojobhunter-reviewed-application.txt',$('letter').value,'text/plain;charset=utf-8')};$('copy').onclick=async()=>{if($('copy').disabled)return;try{await navigator.clipboard.writeText($('letter').value);say('Reviewed text copied; nothing sent.')}catch{say('Clipboard unavailable. Use Download .txt or select the text manually.')}};\n$('question').textContent=questions[0];$('nextQuestion').onclick=()=>{qi=(qi+1)%questions.length;$('question').textContent=questions[qi];$('practiceFeedback').hidden=true};$('practiceCheck').onclick=()=>{$('practiceFeedback').hidden=false;$('practiceFeedback').textContent='You wrote '+$('answer').value.trim().split(/\\s+/).filter(Boolean).length+' words. Self-check: Is the example real? Did you explain your action and result? How does it relate to this job? This is a checklist, not an AI assessment.'};\nfunction tracker(){const l=$('trackerList');l.replaceChildren();state.jobs.forEach(j=>{const a=node('article',undefined,'job');a.append(node('h3',j.title),node('p',j.employer+(j.demo?' · Fictional':'')));const label=node('label','Progress status');label.htmlFor='s-'+j.id;const s=node('select');s.id=label.htmlFor;stages.forEach(t=>{const o=node('option',t);o.value=t;s.append(o)});s.value=j.stage;s.onchange=()=>{j.stage=s.value;save();say('Self-reported status saved; no verification occurred.')};const nl=node('label','Evidence reference / next action — no sensitive details');nl.htmlFor='n-'+j.id;const n=node('textarea');n.id=nl.htmlFor;n.maxLength=1000;n.value=j.note||'';n.onchange=()=>{j.note=n.value;save()};const dl=node('label','Follow-up date — display only');dl.htmlFor='d-'+j.id;const d=node('input');d.id=dl.htmlFor;d.type='date';d.value=j.next||'';d.onchange=()=>{j.next=d.value;save()};a.append(label,s,nl,n,dl,d);l.append(a)})}$('export').onclick=()=>download('autojobhunter-local-records.json',JSON.stringify({exportedAt:new Date().toISOString(),verification:'All progress is self-reported, not independently verified.',...state},null,2),'application/json');$('erase').onclick=()=>{if(!confirm('Erase all local beta data? Saved exports are not erased.'))return;try{localStorage.removeItem(KEY)}catch{}state=blank();$('letter').value='';$('reviewed').checked=false;$('answer').value='';$('practiceFeedback').hidden=true;reviewed();profileForm();counters();tracker();jobs();say('Local beta data erased.')};\n$('sample').onclick=()=>{if(state.jobs.length&&!confirm('Replace local beta data with fictional records?'))return;state=blank();state.profile={name:'Demo Applicant',email:'demo@example.invalid',skills:'cleaning, maintenance, painting',experience:'I have experience cleaning common areas, painting rooms and helping with routine building maintenance.',tickets:'',pay:25,hours:'Part-time',area:'Vancouver'};state.jobs=[{id:'demo-1',title:'Building Maintenance Assistant',employer:'Example Community Building (fictional)',url:'',text:'Cleaning, painting, maintenance and resident service.',pay:28,hours:'Part-time',area:'Vancouver',tickets:'',closing:'',demo:true,stage:'Saved',note:'',next:''},{id:'demo-2',title:'Facilities Technician',employer:'Example Facilities Team (fictional)',url:'',text:'Maintenance, electrical troubleshooting and shift coverage.',pay:32,hours:'Full-time',area:'Burnaby',tickets:'Red Seal electrician',closing:'',demo:true,stage:'Saved',note:'',next:''}];save();profileForm();tab('jobs');say('Fictional sample loaded; no actual vacancy or employment outcome claimed.')};if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('sw.js',{scope:'./'}).catch(()=>{});profileForm();counters();tab('home');\n</script></body></html>","text/html; charset=utf-8"],"/beta/icon.svg":["<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"512\" height=\"512\" viewBox=\"0 0 512 512\"><rect width=\"512\" height=\"512\" rx=\"100\" fill=\"#123d46\"/><path d=\"M115 393 256 105 397 393M175 290H337\" fill=\"none\" stroke=\"white\" stroke-width=\"45\" stroke-linejoin=\"round\"/></svg>","image/svg+xml"],"/beta/manifest.webmanifest":["{\"id\":\"/beta/\",\"name\":\"AutoJobHunter Reviewer Beta\",\"short_name\":\"AutoJobHunter\",\"start_url\":\"./\",\"scope\":\"./\",\"display\":\"standalone\",\"background_color\":\"#eff5f4\",\"theme_color\":\"#123d46\",\"icons\":[{\"src\":\"icon.svg\",\"sizes\":\"any\",\"type\":\"image/svg+xml\",\"purpose\":\"any\"}]}","application/manifest+json"],"/beta/sw.js":["const C='autojobhunter-reviewer-v02';const R=new URL('./',self.location).pathname;self.addEventListener('install',e=>e.waitUntil(caches.open(C).then(c=>c.addAll([R,R+'manifest.webmanifest',R+'icon.svg',R+'reviewer-guide.txt']))));self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin||!u.pathname.startsWith(R))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const cp=r.clone();caches.open(C).then(c=>c.put(e.request,cp))}return r}).catch(()=>caches.match(e.request)))});","application/javascript"],"/beta/reviewer-guide.txt":["AutoJobHunter reviewer beta 0.2 — 3 November 2026\n\nUse fictional details. Load demo, inspect Jobs, prepare and review a letter, download text, practise an interview and update Tracker. Entries are local to this browser; stages are self-reported. Nothing is sent automatically. No live AI, scraping, unattended applications, research enrolment or government endorsement.\n\nAndroid: open in Chrome and check Install app / Add to Home screen. This is a web beta, NOT an APK. Physical-device installation, offline, accessibility and security acceptance tests remain outstanding. Hosting may process ordinary request metadata; form contents are not uploaded by this application. Do not enter IDs, banking, medical or sensitive third-party records. Local storage is not encrypted by this app. Erase clears local records, not downloaded exports.\n\nIndependent pre-application demonstration; not a funding application or claim for historical development reimbursement. No paid APIs or Replit.\n","text/plain; charset=utf-8"],"/beta/autojobhunter-beta.html":["<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#123d46\"><meta name=\"robots\" content=\"noindex,nofollow\"><link rel=\"manifest\" href=\"manifest.webmanifest\"><title>AutoJobHunter | Reviewer beta</title><style>*{box-sizing:border-box}body{margin:0;background:#eff5f4;color:#17333c;font:16px/1.5 system-ui}header{background:#123d46;color:white;padding:22px}header b{font-size:25px}header small{display:block;color:#c1dcdb}main{max-width:1000px;margin:auto;padding:20px 18px 60px}h1{font-size:30px;line-height:1.2}h2{font-size:21px}h3{font-size:18px}nav,.row{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}button,a.btn{background:#087567;color:white;border:0;border-radius:9px;padding:12px 15px;font:600 14px system-ui;cursor:pointer;min-height:44px;text-decoration:none}button:disabled{opacity:.45;cursor:not-allowed}nav button{background:white;color:#17333c;border:1px solid #c5d8d7}nav button[aria-current=page]{background:#123d46;color:white}.card{background:white;border:1px solid #d6e4e4;padding:22px;border-radius:14px;margin:16px 0}.notice{background:#e0efeb;border-left:4px solid #087567;padding:14px;border-radius:8px}.warning{background:#fff5df;border-left:4px solid #b97914;padding:12px;border-radius:8px}.muted,small,footer{color:#536b73}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{display:block;font-size:14px;font-weight:650;margin:12px 0 5px}input,select,textarea{width:100%;min-height:44px;border:1px solid #a8bdc2;border-radius:8px;padding:11px;font:15px system-ui;background:white;color:#17333c}textarea{min-height:100px}.check{display:flex;gap:10px;align-items:start}.check input{width:20px;min-height:20px;height:20px}.job{border-top:1px solid #d6e4e4;padding:18px 0}.score{color:#087567;font-size:21px;font-weight:750}a{color:#086b60}[hidden]{display:none!important}#letter{min-height:300px}#status{background:#17333c;color:white;padding:12px;border-radius:8px;position:sticky;bottom:8px}#status:empty{display:none}:focus-visible{outline:3px solid #d38b14;outline-offset:3px}footer{font-size:12px;margin-top:25px}@media(max-width:700px){.grid{grid-template-columns:1fr}.card{padding:17px}h1{font-size:27px}nav button{padding:11px;font-size:13px}}</style></head><body><header><b>AutoJobHunter</b><small>Reviewer beta 0.2 • Your applications. Your approval.</small></header><main><div class=\"notice\"><strong>Independent demonstration, not a government service.</strong> No automatic applications, background job scanning or live AI. Use fictional details. Form contents stay in this browser; hosting may process ordinary request metadata.</div><nav aria-label=\"Main navigation\"><button data-tab=\"home\">Start</button><button data-tab=\"profile\">My profile</button><button data-tab=\"jobs\">Jobs</button><button data-tab=\"draft\">Application</button><button data-tab=\"practice\">Interview</button><button data-tab=\"tracker\">Tracker</button></nav><section id=\"home\"><div class=\"grid\"><div class=\"card\"><small>NO BANK LOGIN • NO ID UPLOAD • NO FEE</small><h1>One suitable job.<br>One confident next step.</h1><p>Save an opportunity, review your fit, prepare a truthful application and keep track of what actually happened.</p><button id=\"sample\">Load fictional demo</button><p><strong id=\"savedCount\">0</strong> saved jobs · <strong id=\"draftCount\">0</strong> drafts · <strong id=\"appliedCount\">0</strong> applications reported</p><div class=\"warning\">This beta is not encrypted case management. Do not enter identification, banking, medical or sensitive third-party information. Reported progress is not verified progress.</div></div><div class=\"card\"><h2>Reviewer walkthrough</h2><p>Load the demo, open Jobs and compare the qualification warnings. Prepare an application, edit it, confirm its accuracy and download the text. Try Interview, then update Tracker. Nothing is sent to an employer.</p><p>On Android, open in Chrome and check its menu for Install app or Add to Home screen. This is a mobile web beta, <strong>not an APK or Play Store release</strong>. Installation and offline behaviour require device testing.</p><a href=\"reviewer-guide.txt\">Reviewer guide and limitations</a></div></div></section><section id=\"profile\" hidden><form id=\"profileForm\" class=\"card\"><h2>Your profile</h2><p>Only include facts you can support.</p><label for=\"name\">Display / sign-off name</label><input id=\"name\" maxlength=\"100\"><label for=\"email\">Reply email (optional)</label><input id=\"email\" type=\"email\" maxlength=\"160\"><label for=\"skills\">Skills, separated by commas</label><input id=\"skills\" maxlength=\"600\"><label for=\"experience\">Relevant experience in your own words</label><textarea id=\"experience\" maxlength=\"3000\"></textarea><label for=\"tickets\">Actual qualifications / licences, separated by commas</label><input id=\"tickets\" maxlength=\"600\"><label for=\"pay\">Preferred minimum hourly pay, CAD</label><input id=\"pay\" type=\"number\" min=\"0\" max=\"500\" step=\".25\"><label for=\"hours\">Preferred schedule</label><select id=\"hours\"><option>Part-time</option><option>Full-time</option><option>Either</option></select><label for=\"area\">Preferred city / area</label><input id=\"area\" maxlength=\"120\"><p><button type=\"submit\">Save profile on this device</button></p></form></section><section id=\"jobs\" hidden><div class=\"grid\"><div class=\"card\"><h2>Saved opportunities</h2><p class=\"muted\">Checklist weights: skills 40%, pay 20%, schedule 20%, location 20%; missing criteria excluded. Not a hiring probability. Qualifications are checked separately and are not validated.</p><div class=\"row\"><a class=\"btn\" href=\"https://vancouver.craigslist.org/search/jjj\" target=\"_blank\" rel=\"noopener noreferrer\">Craigslist jobs</a><a class=\"btn\" href=\"https://www.jobbank.gc.ca/jobsearch/jobsearch\" target=\"_blank\" rel=\"noopener noreferrer\">Job Bank</a></div><div id=\"jobList\"></div></div><form id=\"jobForm\" class=\"card\"><h2>Add a vacancy manually</h2><label for=\"jobTitle\">Job title</label><input id=\"jobTitle\" maxlength=\"160\" required><label for=\"employer\">Employer</label><input id=\"employer\" maxlength=\"160\" required><label for=\"jobUrl\">Original HTTPS URL, optional</label><input id=\"jobUrl\" type=\"url\" maxlength=\"1500\"><label for=\"jobText\">Posting / duties</label><textarea id=\"jobText\" maxlength=\"10000\"></textarea><label for=\"jobPay\">Hourly pay, CAD, optional</label><input id=\"jobPay\" type=\"number\" min=\"0\" max=\"500\" step=\".25\"><label for=\"jobHours\">Schedule</label><select id=\"jobHours\"><option>Unknown</option><option>Part-time</option><option>Full-time</option><option>Either</option></select><label for=\"jobArea\">City / area</label><input id=\"jobArea\" maxlength=\"120\"><label for=\"jobTickets\">Essential qualifications, separated by commas</label><input id=\"jobTickets\" maxlength=\"1000\"><label for=\"closing\">Closing date, optional</label><input id=\"closing\" type=\"date\"><p><button type=\"submit\">Save vacancy</button></p></form></div></section><section id=\"draft\" hidden><div class=\"card\"><h2>Review-first application</h2><label for=\"selectedJob\">Choose a saved job</label><select id=\"selectedJob\"></select><p id=\"requirementNotice\" class=\"warning\"></p><button id=\"generate\">Create local draft</button><p class=\"muted\">A fixed template uses your own experience. This is not AI-generated. Check the original posting, required credentials, file format and submission route.</p><label for=\"letter\">Editable cover letter</label><textarea id=\"letter\" maxlength=\"12000\"></textarea><label class=\"check\"><input id=\"reviewed\" type=\"checkbox\"><span>I reviewed this exact text and removed unsupported claims.</span></label><div class=\"row\"><button id=\"copy\" disabled>Copy reviewed text</button><button id=\"download\" disabled>Download .txt</button></div><p>Downloading is not applying. Submit separately using the employer's permitted channel.</p></div></section><section id=\"practice\" hidden><div class=\"card\"><h2>Interview practice</h2><p id=\"question\" class=\"notice\"></p><button id=\"nextQuestion\">Next practice question</button><label for=\"answer\">Practise a truthful example</label><textarea id=\"answer\" maxlength=\"5000\"></textarea><p><button id=\"practiceCheck\">Show self-review checklist</button></p><p id=\"practiceFeedback\" class=\"notice\" hidden></p><p class=\"muted\">No video, voice, emotion or personality scoring. Answers stay in this open tab and are not included in exported records.</p></div></section><section id=\"tracker\" hidden><div class=\"card\"><h2>Your activity tracker</h2><p>All stages are self-reported. No verification or notification to an employer or government occurs. Follow-up dates are display-only, not background reminders.</p><button id=\"export\">Export local records (.json)</button><div id=\"trackerList\"></div></div><div class=\"card\"><h2>Your data, your choice</h2><p>Browser storage is not encrypted by this app. Device access can expose entries. Browser clearing or uninstalling may remove them. Export only to a private location.</p><button id=\"erase\">Erase all beta data on this device</button><p>Exports saved elsewhere are not erased.</p></div></section><footer>AutoJobHunter reviewer beta 0.2. No WorkBC endorsement, funding approval or research enrolment. No paid APIs or Replit. Physical Android, accessibility, installation, offline and security acceptance tests remain outstanding.</footer><div id=\"status\" role=\"status\" aria-live=\"polite\"></div></main><script>\n'use strict';const $=id=>document.getElementById(id),KEY='autojobhunter-reviewer-v02';const blank=()=>({version:2,profile:{name:'',email:'',skills:'',experience:'',tickets:'',pay:25,hours:'Part-time',area:'Vancouver'},jobs:[],drafts:{},drafted:[]});let state=blank(),qi=0;try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&s.version===2&&s.profile&&Array.isArray(s.jobs)&&s.drafts&&Array.isArray(s.drafted))state=s}catch{}\nconst stages=['Saved','Drafted','Applied — self-reported','Employer reply — self-reported','Interview — self-reported','Offer — self-reported','Hired — self-reported','Closed / not proceeding'];const questions=['Tell me about a time you solved a practical problem at work.','How would you handle a task you have not been trained to do safely?','How do you prioritise several urgent requests?','What interests you about this role?','Describe a disagreement you handled respectfully.'];function say(t){$('status').textContent=t}function counters(){$('savedCount').textContent=state.jobs.length;$('draftCount').textContent=state.drafted.length;$('appliedCount').textContent=state.jobs.filter(j=>stages.slice(2,7).includes(j.stage)).length}function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{say('Storage unavailable. Export before closing this tab.')}counters()}function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}function btn(text,fn){const b=node('button',text);b.type='button';b.onclick=fn;return b}function terms(s){return String(s||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean)}function safeUrl(s){try{const u=new URL(s);return u.protocol==='https:'&&!u.username&&!u.password}catch{return false}}function profileForm(){for(const k of Object.keys(state.profile))if($(k))$(k).value=state.profile[k]}function tab(id){document.querySelectorAll('main>section').forEach(s=>s.hidden=s.id!==id);document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(id==='jobs')jobs();if(id==='tracker')tracker();if(id==='draft')select();if(id==='profile')profileForm();window.scrollTo(0,0)}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));\nfunction fit(j){const p=state.profile,c=[],w=terms(p.skills),t=(j.title+' '+j.text).toLowerCase();if(w.length){const n=w.filter(x=>t.includes(x)).length;c.push([40,n/w.length,'Skills mentioned '+n+'/'+w.length])}if(Number(p.pay)>0&&j.pay!==null)c.push([20,j.pay>=p.pay?1:0,'Pay '+(j.pay>=p.pay?'meets':'below')+' preference']);if(j.hours!=='Unknown')c.push([20,p.hours==='Either'||j.hours==='Either'||j.hours===p.hours?1:0,'Schedule '+j.hours]);if(p.area&&j.area)c.push([20,j.area.toLowerCase().includes(p.area.toLowerCase())?1:0,'Area '+j.area]);const total=c.reduce((a,x)=>a+x[0],0);return{score:total?Math.round(100*c.reduce((a,x)=>a+x[0]*x[1],0)/total):null,labels:c.map(x=>x[2]),missing:terms(j.tickets).filter(x=>!terms(p.tickets).includes(x))}}function warning(j){const m=fit(j).missing;return m.length?'Check essential qualifications: '+m.join(', ')+'. Not listed in your profile. Do not claim them unless true.':terms(j.tickets).length?'Entered qualification text matches your profile. Validity and equivalence are NOT verified.':'No essential qualifications entered. Check the complete original posting.'}\n$('profileForm').onsubmit=e=>{e.preventDefault();for(const k of Object.keys(state.profile))state.profile[k]=k==='pay'?Number($(k).value):$(k).value.trim();save();say('Profile saved locally. Existing drafts are not automatically rewritten.')};function jobs(){const list=$('jobList');list.replaceChildren();if(!state.jobs.length)list.append(node('p','No jobs yet. Load the demo or add a vacancy.'));state.jobs.forEach(j=>{const f=fit(j),a=node('article',undefined,'job');a.append(node('h3',j.title),node('p',j.employer+' · '+(j.area||'Area unknown')+' · '+(j.pay===null?'Pay unknown':'$'+j.pay+'/hour')+' · '+j.hours),node('strong',j.demo?'FICTIONAL DEMO VACANCY':'User-entered vacancy; not verified'),node('p',f.score===null?'Unscored':f.score+'% checklist fit','score'),node('p',f.labels.join(' | ')),node('p',warning(j),'warning'));if(j.closing&&j.closing<new Date().toISOString().slice(0,10))a.append(node('p','Closing date has passed. Confirm availability.','warning'));a.append(btn('Prepare application',()=>{tab('draft');$('selectedJob').value=j.id;loadDraft()}));if(j.url&&safeUrl(j.url)){const link=node('a',' Open source vacancy');link.href=j.url;link.target='_blank';link.rel='noopener noreferrer';a.append(link)}list.append(a)})}\n$('jobForm').onsubmit=e=>{e.preventDefault();const url=$('jobUrl').value.trim();if(url&&!safeUrl(url)){say('Use an HTTPS URL without embedded credentials.');return}state.jobs.push({id:typeof crypto.randomUUID==='function'?crypto.randomUUID():String(Date.now()),title:$('jobTitle').value.trim(),employer:$('employer').value.trim(),url,text:$('jobText').value.trim(),pay:$('jobPay').value===''?null:Number($('jobPay').value),hours:$('jobHours').value,area:$('jobArea').value.trim(),tickets:$('jobTickets').value.trim(),closing:$('closing').value,stage:'Saved',note:'',next:'',demo:false});save();e.target.reset();jobs();say('Vacancy saved. Its authenticity and availability are not verified.')};function chosen(){return state.jobs.find(j=>j.id===$('selectedJob').value)}function select(){const old=$('selectedJob').value;$('selectedJob').replaceChildren();state.jobs.forEach(j=>{const o=node('option',j.title+' — '+j.employer);o.value=j.id;$('selectedJob').append(o)});if(state.jobs.some(j=>j.id===old))$('selectedJob').value=old;$('generate').disabled=!state.jobs.length;loadDraft()}function reviewed(){const ready=$('reviewed').checked&&$('letter').value.trim().length>0;$('copy').disabled=!ready;$('download').disabled=!ready}function loadDraft(){const j=chosen();$('letter').value=j?(state.drafts[j.id]||''):'';$('requirementNotice').textContent=j?warning(j):'Save a job first.';$('reviewed').checked=false;reviewed()}$('selectedJob').onchange=loadDraft;\n$('generate').onclick=()=>{const j=chosen();if(!j)return;const p=state.profile,lines=['Dear Hiring Manager,','','I am applying for the '+j.title+' position at '+j.employer+'.','',p.experience?'My relevant experience: '+p.experience:'[Add your truthful relevant experience.]','','I would welcome an opportunity to discuss the role and confirm its requirements.','','Thank you for your consideration.','','Sincerely,',p.name||'[Your name]'];if(p.email)lines.push(p.email);$('letter').value=lines.join('\\n');state.drafts[j.id]=$('letter').value;if(!state.drafted.includes(j.id))state.drafted.push(j.id);if(j.stage==='Saved')j.stage='Drafted';$('reviewed').checked=false;reviewed();save();say('Template draft created; nothing sent.')};$('letter').oninput=()=>{const j=chosen();if(j){state.drafts[j.id]=$('letter').value;save()}$('reviewed').checked=false;reviewed()};$('reviewed').onchange=reviewed;function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=node('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}$('download').onclick=()=>{if(!$('download').disabled)download('autojobhunter-reviewed-application.txt',$('letter').value,'text/plain;charset=utf-8')};$('copy').onclick=async()=>{if($('copy').disabled)return;try{await navigator.clipboard.writeText($('letter').value);say('Reviewed text copied; nothing sent.')}catch{say('Clipboard unavailable. Use Download .txt or select the text manually.')}};\n$('question').textContent=questions[0];$('nextQuestion').onclick=()=>{qi=(qi+1)%questions.length;$('question').textContent=questions[qi];$('practiceFeedback').hidden=true};$('practiceCheck').onclick=()=>{$('practiceFeedback').hidden=false;$('practiceFeedback').textContent='You wrote '+$('answer').value.trim().split(/\\s+/).filter(Boolean).length+' words. Self-check: Is the example real? Did you explain your action and result? How does it relate to this job? This is a checklist, not an AI assessment.'};\nfunction tracker(){const l=$('trackerList');l.replaceChildren();state.jobs.forEach(j=>{const a=node('article',undefined,'job');a.append(node('h3',j.title),node('p',j.employer+(j.demo?' · Fictional':'')));const label=node('label','Progress status');label.htmlFor='s-'+j.id;const s=node('select');s.id=label.htmlFor;stages.forEach(t=>{const o=node('option',t);o.value=t;s.append(o)});s.value=j.stage;s.onchange=()=>{j.stage=s.value;save();say('Self-reported status saved; no verification occurred.')};const nl=node('label','Evidence reference / next action — no sensitive details');nl.htmlFor='n-'+j.id;const n=node('textarea');n.id=nl.htmlFor;n.maxLength=1000;n.value=j.note||'';n.onchange=()=>{j.note=n.value;save()};const dl=node('label','Follow-up date — display only');dl.htmlFor='d-'+j.id;const d=node('input');d.id=dl.htmlFor;d.type='date';d.value=j.next||'';d.onchange=()=>{j.next=d.value;save()};a.append(label,s,nl,n,dl,d);l.append(a)})}$('export').onclick=()=>download('autojobhunter-local-records.json',JSON.stringify({exportedAt:new Date().toISOString(),verification:'All progress is self-reported, not independently verified.',...state},null,2),'application/json');$('erase').onclick=()=>{if(!confirm('Erase all local beta data? Saved exports are not erased.'))return;try{localStorage.removeItem(KEY)}catch{}state=blank();$('letter').value='';$('reviewed').checked=false;$('answer').value='';$('practiceFeedback').hidden=true;reviewed();profileForm();counters();tracker();jobs();say('Local beta data erased.')};\n$('sample').onclick=()=>{if(state.jobs.length&&!confirm('Replace local beta data with fictional records?'))return;state=blank();state.profile={name:'Demo Applicant',email:'demo@example.invalid',skills:'cleaning, maintenance, painting',experience:'I have experience cleaning common areas, painting rooms and helping with routine building maintenance.',tickets:'',pay:25,hours:'Part-time',area:'Vancouver'};state.jobs=[{id:'demo-1',title:'Building Maintenance Assistant',employer:'Example Community Building (fictional)',url:'',text:'Cleaning, painting, maintenance and resident service.',pay:28,hours:'Part-time',area:'Vancouver',tickets:'',closing:'',demo:true,stage:'Saved',note:'',next:''},{id:'demo-2',title:'Facilities Technician',employer:'Example Facilities Team (fictional)',url:'',text:'Maintenance, electrical troubleshooting and shift coverage.',pay:32,hours:'Full-time',area:'Burnaby',tickets:'Red Seal electrician',closing:'',demo:true,stage:'Saved',note:'',next:''}];save();profileForm();tab('jobs');say('Fictional sample loaded; no actual vacancy or employment outcome claimed.')};if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('sw.js',{scope:'./'}).catch(()=>{});profileForm();counters();tab('home');\n</script></body></html>","text/html; charset=utf-8"]};addEventListener('fetch',event=>{const request=event.request,path=new URL(request.url).pathname;if(path==='/'||path==='/beta'){event.respondWith(Response.redirect(new URL('/beta/',request.url),302));return;}if(request.method!=='GET'&&request.method!=='HEAD'){event.respondWith(new Response('Method not allowed',{status:405,headers:{Allow:'GET, HEAD'}}));return;}const asset=ASSETS[path];if(!asset){event.respondWith(new Response('Not found',{status:404}));return;}event.respondWith(new Response(request.method==='HEAD'?null:asset[0],{headers:{'Content-Type':asset[1],...(path.endsWith('/autojobhunter-beta.html')?{'Content-Disposition':'attachment; filename=autojobhunter-beta.html'}:{}),'Cache-Control':'no-cache','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','X-Robots-Tag':'noindex, nofollow','Content-Security-Policy':"default-src 'self'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; worker-src 'self'; manifest-src 'self'; object-src 'none'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'"}}));});